67	std::pair<const IColumn *, size_t> getBlockColumnAndRow(const RowRef * row_ref, size_t column_index)
68	{
69	    if (const auto * replicated_column_from_block = (*row_ref->columns_info).replicated_columns[column_index])
70	        return {replicated_column_from_block->getNestedColumn().get(), replicated_column_from_block->getIndexes().getIndexAt(row_ref->row_num)};
