74	void LazyOutput::buildJoinGetOutput(size_t size_to_reserve, MutableColumns & columns, const UInt64 * row_refs_begin, const UInt64 * row_refs_end) const
75	{
76	    for (size_t i = 0; i < columns.size(); ++i)
77	    {
78	        auto & col = columns[i];
79	        col->reserve(col->size() + size_to_reserve);
80	        for (const UInt64 * row_ref_i = row_refs_begin; row_ref_i != row_refs_end; ++row_ref_i)
81	        {
82	            if (!*row_ref_i)
83	            {
84	                type_name[i].type->insertDefaultInto(*col);
85	                continue;
86	            }
87	            const auto * row_ref = reinterpret_cast<const RowRef *>(*row_ref_i);
88	            const auto [column_from_block, row_num] = getBlockColumnAndRow(row_ref, right_indexes[i]);
89	            if (auto * nullable_col = typeid_cast<ColumnNullable *>(col.get()); nullable_col && !column_from_block->isNullable())
90	                nullable_col->insertFromNotNullable(*column_from_block, row_num);
91	            else
92	                col->insertFrom(*column_from_block, row_num);
93	        }
94	    }
