97	/// Returns how many rows were added to columns, up to rows_limit
98	size_t LazyOutput::buildOutputFromBlocksLimitAndOffset(
99	    MutableColumns & columns, const UInt64 * row_refs_begin, const UInt64 * row_refs_end,
100	    const PaddedPODArray<UInt64> & left_sizes, const IColumn::Offsets & left_offsets,
101	    size_t rows_offset, size_t rows_limit, size_t bytes_limit) const
102	{
103	    if (columns.empty())
104	        return rows_limit;
105	
106	    ColumnsWithRowNumbers columns_with_row_numbers;
107	    auto & many_columns = columns_with_row_numbers.columns;
108	    auto & row_nums = columns_with_row_numbers.row_numbers;
109	    many_columns.reserve(rows_limit);
110	    row_nums.reserve(rows_limit);
111	
112	    size_t row_idx = 0;
113	    size_t total_byte_size = 0;
114	    size_t left_idx = 0; /// position in non-replicated left block
115	    for (const UInt64 * row_ref_i = row_refs_begin; rows_limit > 0 && row_ref_i != row_refs_end; ++row_ref_i)
116	    {
117	        if (*row_ref_i)
118	        {
119	            const RowRefList * row_ref_list = reinterpret_cast<const RowRefList *>(*row_ref_i);
120	            for (auto it = row_ref_list->begin(); rows_limit > 0 && it.ok(); ++it)
121	            {
122	                if (row_idx < rows_offset)
123	                {
124	                    ++row_idx;
125	                    continue;
126	                }
127	
128	                if (bytes_limit)
129	                {
130	                    /// Check if we are still in the same left row or moved to next one
131	                    while (row_idx >= left_offsets[left_idx])
132	                        ++left_idx;
133	                    chassert(left_sizes.size() > left_idx);
134	                    total_byte_size += left_sizes[left_idx];
135	
136	                    /// Add size of right matched rows
137	                    for (const auto & col: (*it->columns_info).columns)
138	                        total_byte_size += col->byteSizeAt(it->row_num);
139	                }
140	
141	                ++row_idx;
142	                --rows_limit;
143	                many_columns.emplace_back(it->columns_info);
144	                row_nums.emplace_back(it->row_num);
145	
146	                if (bytes_limit && total_byte_size > bytes_limit)
147	                    rows_limit = 0;
148	            }
149	        }
150	        else
151	        {
152	            if (row_idx < rows_offset)
153	            {
154	                ++row_idx;
155	                continue;
156	            }
157	            many_columns.emplace_back(nullptr);
158	            row_nums.emplace_back(0);
159	            ++row_idx;
160	            --rows_limit;
161	            /// Here we do not account byte size, since limit targets to avoid only huge blocks with large strings being replicated many times.
162	            /// In case of non-matched rows, left row is added only once and right columns are filled with defaults which have fixed small size.
163	        }
164	    }
165	
166	    for (size_t i = 0; i < columns.size(); ++i)
167	    {
168	        columns[i]->fillFromBlocksAndRowNumbers(type_name[i].type, right_indexes[i], columns_with_row_numbers);
169	    }
170	    return row_nums.size();
171	}
